import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
a = list(map(int, data[1:]))

dp = [0] * (n + 1)
last_occurrence = {}
next_occurrence = [n] * n

for i in range(n - 1, -1, -1):
    if a[i] in last_occurrence:
        next_occurrence[i] = last_occurrence[a[i]]
    last_occurrence[a[i]] = i

rare_city_threshold = 10
city_count = {}

for code in a:
    if code in city_count:
        city_count[code] += 1
    else:
        city_count[code] = 1

for i in range(n):
    city_codes = set()
    max_xor = 0
    j = i
    segment_length = 0
    while j < n and (a[j] not in city_codes):
        city_codes.add(a[j])
        max_xor ^= a[j]
        j = next_occurrence[j]
        segment_length += 1

    for code in city_codes:
        if city_count[code] < rare_city_threshold and segment_length > 3:
            max_xor = 0
            break

    dp[j] = max(dp[j], dp[i] + max_xor)

print(dp[n])

